"""Given a maps x->y, b maps y->z, return map of x->z."""
def buildIndirectMapping(a: Any, b: Any) -> object {
    assert (len(a) == len(b));
    assert isinstance(`list(b.keys())[0], `type(`list(a.values())[0]));
    c = `dict();
    for x in a.keys() {
        y = a[x];
        z = b[y];
        c[x] = z;
    }
    return c;
}

test_blocks:
test "t0" {
    assert (
        buildIndirectMapping({"a": 1, "b": 2, "c": 3}, {1: "aa", 2: "bb", 3: "cc"})
        == {"a": "aa", "b": "bb", "c": "cc"}
    );;
}

test "t1" {
    assert (
        buildIndirectMapping({"a": 1, "b": 2}, {1: "aa", 2: "bb"})
        == {"a": "aa", "b": "bb"}
    );;
}

test "t2" {
    assert (
        buildIndirectMapping(`dict(zip("abc", range(3))), `dict(zip(range(3), "def")))
        == `dict(zip("abc", "def"))
    );;
}

